{
  "decision": "needs_more_evidence",
  "objections": [
    {
      "severity": "critical",
      "problem": "The claim states 'always stretch your body after waking up', but the study only tested a single leg stretching in young men without specifying timing relative to waking up or whole-body stretching.",
      "requested_action": "More evidence on timing of stretching relative to waking up and whole-body application is needed."
    },
    {
      "severity": "critical",
      "problem": "The study does not address the 'boost circulation' claim as it measured arterial stiffness (PWV), not direct circulation improvement.",
      "requested_action": "More evidence linking arterial stiffness reduction to improved circulation is needed."
    },
    {
      "severity": "critical",
      "problem": "The study only examined acute effects (immediate and 15 min) without long-term or habitual stretching context.",
      "requested_action": "More evidence on long-term effects of daily stretching after waking up is needed."
    }
  ],
  "remaining_gaps": [
    "Timing of stretching relative to waking up",
    "Direct evidence of circulation improvement",
    "Long-term effects of habitual stretching"
  ]
}
